def apply(inputs,premises):
    spans=inputs.get('source_spans',[])
    source_output=inputs.get('source_output',{})
    rows=answer_rows(inputs.get('semantic_answers',[]))
    byid={}
    for row in rows:
        if isinstance(row,dict) and isinstance(row.get('id'),str):
            byid[row.get('id')]=row
    unit_text={}
    all_ids=[]
    for span in spans:
        uid=span.get('id')
        text=span.get('text','')
        if not isinstance(text,str):
            text=str(text)
        unit_text[uid]=text
        all_ids.append(uid)
    statements=[]
    for row in source_output.get('statements',[]):
        if isinstance(row,dict) and isinstance(row.get('term'),list):
            add_statement(statements,row.get('term'),row.get('support_ids',[]))
    unresolved=[]
    disclosure=byid.get('disclosure_scout_v2_complete')
    disposal=byid.get('disposal_scout_v2_complete')
    if not isinstance(disclosure,dict):
        unresolved.append('class-specific disclosure review unread')
    elif disclosure.get('choice')=='none_in_complete_source':
        add_statement(statements,['complete_source_rule_absence','class-specific personnel and professional-service disclosure norms'],all_ids)
    elif disclosure.get('choice')=='candidate_found':
        for uid in evidence_ids(disclosure):
            qid='disclosure_effect_v2_'+str(uid)
            effect=byid.get(qid)
            if not isinstance(effect,dict) or effect.get('choice')=='unknown':
                add_unique(unresolved,'unresolved disclosure window '+str(uid))
            else:
                compose_disclosure(statements,unresolved,effect,byid.get('disclosure_access_v2_'+str(uid)),byid.get('disclosure_safeguard_v2_'+str(uid)),unit_text)
    else:
        unresolved.append('class-specific disclosure review unknown')
    if not isinstance(disposal,dict):
        unresolved.append('disposal and retention review unread')
    elif disposal.get('choice')=='none_in_complete_source':
        add_statement(statements,['complete_source_rule_absence','return destruction and post-disposal retention norms'],all_ids)
    elif disposal.get('choice')=='candidate_found':
        for uid in evidence_ids(disposal):
            profile=byid.get('disposal_profile_v2_'+str(uid))
            if not isinstance(profile,dict) or profile.get('choice')=='unknown':
                add_unique(unresolved,'unresolved disposal window '+str(uid))
            else:
                compose_disposal(statements,unresolved,profile,unit_text)
    else:
        unresolved.append('disposal and retention review unknown')
    return {'statements':statements,'complete':len(unresolved)==0,'unresolved':unresolved}

def answer_rows(value):
    if isinstance(value,list):
        return value
    if isinstance(value,dict):
        answers=value.get('answers')
        if isinstance(answers,list):
            return answers
        if isinstance(answers,dict):
            return list(answers.values())
        return list(value.values())
    return []

def add_unique(xs,value):
    if value not in xs:
        xs.append(value)

def add_statement(out,term,support):
    ids=[]
    for uid in support:
        if uid not in ids:
            ids.append(uid)
    for row in out:
        if row.get('term')==term:
            return
    out.append({'term':term,'support_ids':ids})

def evidence_ids(answer):
    out=[]
    if not isinstance(answer,dict):
        return out
    evidence=answer.get('evidence',[])
    if isinstance(evidence,dict):
        evidence=[evidence]
    for item in evidence:
        if isinstance(item,dict):
            uid=item.get('unit_id')
            if uid not in out:
                out.append(uid)
    return out

def combined_ids(answers):
    out=[]
    for answer in answers:
        for uid in evidence_ids(answer):
            if uid not in out:
                out.append(uid)
    return out

def evidence_text(answer,unit_text):
    parts=[]
    for uid in evidence_ids(answer):
        text=unit_text.get(uid,'')
        if text and text not in parts:
            parts.append(text)
    return ' '.join(parts)

def first_matching_text(answer,unit_text,needles):
    for uid in evidence_ids(answer):
        text=unit_text.get(uid,'')
        low=text.casefold()
        for needle in needles:
            if needle in low:
                return text
    ids=evidence_ids(answer)
    if ids:
        return unit_text.get(ids[0],'')
    return ''

def make_union(items):
    if not items:
        return None
    value=items[len(items)-1]
    i=len(items)-2
    while i>=0:
        value=['participant_union',items[i],value]
        i-=1
    return value

def actor_from_text(text):
    if 'volunteer' in text.casefold():
        return ['named_recipient','Volunteer']
    return ['receiving_party']

def recipient_term(choice,text):
    low=text.casefold()
    owner=['receiving_party']
    items=[]
    if choice in ('permission_employees_and_services','permission_employees_only'):
        items.append(['employees_of',owner])
    if choice in ('permission_employees_and_services','permission_services_only'):
        if 'contractor' in low:
            items.append(['independent_contractors_of',owner])
        if 'consultant' in low:
            items.append(['consultants_of',owner])
        if 'agent' in low:
            items.append(['agents_of',owner])
        if 'professional adviser' in low or 'professional advisor' in low:
            items.append(['professional_advisors_of',owner])
        if 'legal adviser' in low or 'legal advisor' in low or 'attorney' in low:
            items.append(['legal_advisors_of',owner])
        if 'financial adviser' in low or 'financial advisor' in low:
            items.append(['financial_advisors_of',owner])
        if 'accountant' in low:
            items.append(['accountants_of',owner])
        if 'lender' in low:
            items.append(['lenders_of',owner])
        if 'director' in low:
            items.append(['directors_of',owner])
        if 'officer' in low or 'official' in low:
            items.append(['officers_of',owner])
        has_service=False
        for item in items:
            if item[0]!='employees_of':
                has_service=True
        if not has_service:
            items.append(['source_named_service_recipients_of',owner,text])
    return make_union(items)

def condition_term(access,safeguard,unit_text):
    conditions=[]
    ac=access.get('choice')
    if ac=='need_to_know_required':
        conditions.append(['need_to_know',first_matching_text(access,unit_text,['need to know','need-to-know'])])
    elif ac=='extent_necessary_required':
        conditions.append(['extent_necessary',first_matching_text(access,unit_text,['necessary','required for'])])
    elif ac=='need_and_extent_required':
        conditions.append(['need_to_know',first_matching_text(access,unit_text,['need to know','need-to-know'])])
        conditions.append(['extent_necessary',first_matching_text(access,unit_text,['necessary','required for'])])
    sc=safeguard.get('choice')
    if sc in ('written_confidentiality_required','confidentiality_duty_without_written_form'):
        conditions.append(['confidentiality_bound',first_matching_text(safeguard,unit_text,['confidentiality','confidential','non-disclosure','nondisclosure','obligations'])])
    if not conditions:
        return ['no_condition']
    value=conditions[0]
    i=1
    while i<len(conditions):
        value=['and_condition',value,conditions[i]]
        i+=1
    return value

def compose_disclosure(statements,unresolved,effect,access,safeguard,unit_text):
    choice=effect.get('choice')
    support=evidence_ids(effect)
    text=evidence_text(effect,unit_text)
    actor=actor_from_text(text)
    if choice in ('permission_employees_and_services','permission_employees_only','permission_services_only'):
        if not isinstance(access,dict) or not isinstance(safeguard,dict):
            add_unique(unresolved,'permission conditions unread for '+effect.get('id',''))
            return
        if access.get('choice') in ('unknown','no_operational_permission') or safeguard.get('choice') in ('unknown','no_operational_permission'):
            add_unique(unresolved,'permission condition classification unresolved for '+effect.get('id',''))
            return
        recipient=recipient_term(choice,text)
        if recipient is None:
            add_unique(unresolved,'permission recipient binding unresolved for '+effect.get('id',''))
            return
        support=combined_ids([effect,access,safeguard])
        condition=condition_term(access,safeguard,unit_text)
        add_statement(statements,['permission',actor,['disclose',['confidential_information'],recipient],condition],support)
    elif choice=='prohibition_third_parties':
        add_statement(statements,['prohibition',actor,['disclose',['confidential_information'],['third_parties']],['no_condition'],['no_exceptions']],support)
    elif choice=='prohibition_outsiders_of_actor_group':
        group=['participant_union',['receiving_party'],['representatives_of',['receiving_party']]]
        add_statement(statements,['prohibition',group,['disclose',['confidential_information'],['outsiders_to',group]],['no_condition'],['no_exceptions']],support)
    elif choice=='permission_other_recipients':
        add_unique(unresolved,'other permission recipient remains source-specific for '+effect.get('id',''))

def information_scope(text):
    low=text.casefold()
    items=[['confidential_information']]
    if 'copy' in low or 'copies' in low or 'reproduction' in low:
        items.append(['copies_of',['confidential_information']])
    if 'note' in low or 'abstract' in low or 'analysis' in low or 'summary' in low or 'extract' in low or 'derivative' in low:
        items.append(['derivative_materials_of',['confidential_information']])
    value=items[len(items)-1]
    i=len(items)-2
    while i>=0:
        value=['information_bundle',items[i],value]
        i-=1
    return value

def trigger_for(choice):
    if choice=='agreement_termination_disposal':
        return ['agreement_termination']
    if choice=='service_termination_disposal':
        return ['service_termination']
    if choice=='relationship_termination_disposal':
        return ['relationship_termination']
    if choice=='relationship_nonformation_deadline_disposal':
        return ['relationship_nonformation_deadline']
    if choice=='request_disposal':
        return ['request_by',['disclosing_party']]
    if choice=='agreement_termination_or_request_disposal':
        return ['trigger_alternative',['agreement_termination'],['request_by',['disclosing_party']]]
    return None

def compose_disposal(statements,unresolved,profile,unit_text):
    choice=profile.get('choice')
    support=evidence_ids(profile)
    text=evidence_text(profile,unit_text)
    low=text.casefold()
    actor=actor_from_text(text)
    info=information_scope(text)
    if choice=='retention_allowed_after_disposal':
        condition=['retention_condition',first_matching_text(profile,unit_text,['required by law','compliance','archive','backup','retain'])]
        add_statement(statements,['retention_permission',actor,info,['after_disposal'],condition],support)
        return
    if choice=='retention_forbidden_after_disposal':
        add_statement(statements,['retention_prohibition',actor,info,['after_disposal']],support)
        return
    trigger=trigger_for(choice)
    if trigger is not None:
        do_return='return' in low
        do_destroy=('destroy' in low or 'destruction' in low) and 'not destroyed' not in low
        if not do_return and not do_destroy:
            add_unique(unresolved,'disposal action evidence missing for '+profile.get('id',''))
            return
        if do_return and do_destroy:
            action=['action_alternative',['return_to',info,['disclosing_party']],['destroy',info]]
        elif do_return:
            action=['return_to',info,['disclosing_party']]
        else:
            action=['destroy',info]
        add_statement(statements,['disposal_obligation',actor,action,trigger,['no_exceptions']],support)
    elif choice=='other_disposal_or_retention':
        add_unique(unresolved,'other disposal pattern remains unresolved for '+profile.get('id',''))

