def context_window(spans,uid,before,after):
    pos=-1
    i=0
    while i<len(spans):
        if spans[i].get('id')==uid:
            pos=i
        i+=1
    if pos<0:
        return [uid]
    lo=max(0,pos-before)
    hi=min(len(spans),pos+after+1)
    out=[]
    i=lo
    while i<hi:
        out.append(spans[i].get('id'))
        i+=1
    return out

