        return False
    return x[0] in ('receiving_party','party','named_recipient')

def class_tags(x,defs):
    tags=set()
    todo=[x]
    seen=set()
    while todo:
        y=todo.pop()
        if not isinstance(y,list) or not y:
            continue
        n=y[0]
        if n=='representatives_of':
            k=str(y[1]) if len(y)>1 else ''
            if k not in seen:
                seen.add(k)
                for d in defs:
                    if str(d[0])==k or (isinstance(d[0],list) and d[0] and d[0][0]=='party'):
                        todo.append(d[1])
            continue
        if n=='internal_personnel_of' and len(y)>1 and owner_ok(y[1]):
            tags.add('employees_of')
        if n in ('employees_of','directors_of','officers_of','legal_advisors_of','financial_advisors_of','professional_advisors_of','accountants_of','consultants_of','agents_of','independent_contractors_of','lenders_of'):
            if len(y)>1 and owner_ok(y[1]):
                tags.add(n)
            continue
        if n=='third_parties':
            tags.add(n)
            continue
        i=1
        while i<len(y):
            if isinstance(y[i],list):
                todo.append(y[i])
            i+=1
    return tags

def unique(values):
    out=[]
    for value in values:
        if value not in out:
            out.append(value)
    return out

def apply(inputs,premises):
    task=inputs.get('task_id')
    if task not in ('nda-5','nda-7','nda-16','nda-20'):
        return {'handled':False,'answer':None,'used_nodes':[]}
    entries=collect_entries(premises.get('nodes',[]),premises.get('roots',[]))
    if task in ('nda-5','nda-7'):
        return disclosure_decision(task,entries)
    disposal=[]
    retention_yes=[]
    retention_no=[]
    absence=[]
    for term,root in entries:
        if term[0]=='disposal_obligation' and len(term)==5:
            disposal.append((term,root))
        elif term[0] in ('retention_permission','retention_exception'):
            retention_yes.append(root)
        elif term[0]=='retention_prohibition':
            retention_no.append(root)
        elif term[0]=='complete_source_rule_absence' and len(term)>1 and term[1]=='return destruction and post-disposal retention norms':
            absence.append(root)
    if task=='nda-16':
        relevant=[]
        entailed=[]
        for term,root in disposal:
            action=term[2]
            trigger=term[3]
            if not (has_tag(action,'return_to') or has_tag(action,'destroy')):
                continue
            relevant.append(root)
            if has_tag(trigger,'agreement_termination') or has_tag(trigger,'service_termination') or has_tag(trigger,'relationship_termination') or has_tag(trigger,'relationship_nonformation_deadline'):
                entailed.append(root)
        if entailed:
            return {'handled':True,'answer':'Entailment','used_nodes':unique(entailed)}
        if relevant:
            return {'handled':True,'answer':'NotMentioned','used_nodes':unique(relevant)}
        if absence:
            return {'handled':True,'answer':'NotMentioned','used_nodes':unique(absence)}
        return {'handled':False,'answer':None,'used_nodes':[]}
    if retention_yes:
        return {'handled':True,'answer':'Entailment','used_nodes':unique(retention_yes)}
    if retention_no:
        return {'handled':True,'answer':'Contradiction','used_nodes':unique(retention_no)}
    relevant=[]
    contrary=[]
    for term,root in disposal:
        action=term[2]
        exceptions=term[4]
        if not (has_tag(action,'return_to') or has_tag(action,'destroy')):
            continue
        relevant.append(root)
        if has_tag(action,'confidential_information') and has_tag(action,'copies_of') and exceptions==['no_exceptions']:
            contrary.append(root)
    if contrary:
        return {'handled':True,'answer':'Contradiction','used_nodes':unique(contrary)}
    if relevant:
        return {'handled':True,'answer':'NotMentioned','used_nodes':unique(relevant)}
    if absence:
        return {'handled':True,'answer':'NotMentioned','used_nodes':unique(absence)}
    return {'handled':False,'answer':None,'used_nodes':[]}

def disclosure_decision(task,entries):
    permissions=[]
    prohibitions=[]
    relevant=[]
    absence=[]
    for term,root in entries:
        if term[0]=='complete_source_rule_absence' and len(term)>1 and term[1]=='class-specific personnel and professional-service disclosure norms':
            absence.append(root)
        if term[0] not in ('permission','prohibition') or len(term)<3:
            continue
        action=term[2]
        if not isinstance(action,list) or len(action)!=3 or action[0]!='disclose' or not has_tag(action[1],'confidential_information'):
            continue
        relevant.append(root)
        item=(root,role_tags(action[2]),action[2])
        if term[0]=='permission':
            permissions.append(item)
        else:
            prohibitions.append(item)
    wanted={'employees_of'} if task=='nda-5' else {'consultants_of','agents_of','independent_contractors_of','legal_advisors_of','financial_advisors_of','professional_advisors_of','accountants_of','source_named_service_recipients_of','third_parties'}
    for root,tags,recipient in permissions:
        if tags.intersection(wanted):
            return {'handled':True,'answer':'Entailment','used_nodes':[root]}
    for root,tags,recipient in prohibitions:
        if has_tag(recipient,'outsiders_to'):
            continue
        if tags.intersection(wanted):
            return {'handled':True,'answer':'Contradiction','used_nodes':[root]}
    if relevant:
        return {'handled':True,'answer':'NotMentioned','used_nodes':unique(relevant)}
    if absence:
        return {'handled':True,'answer':'NotMentioned','used_nodes':unique(absence)}
    return {'handled':False,'answer':None,'used_nodes':[]}

def collect_entries(nodes,roots):
    byid={}
    for node in nodes:
        byid[node.get('id')]=node
    entries=[]
    for root in roots:
        todo=[root]
        seen=set()
        while todo:
            nid=todo.pop()
            if nid in seen or nid not in byid:
                continue
            seen.add(nid)
            node=byid[nid]
            for term in subterms(node.get('term')):
                entries.append((term,root))
            for child in node.get('child_ids',[]):
                todo.append(child)
    return entries

def role_tags(value):
    tags=set()
    for item in subterms(value):
        if item[0] in ('employees_of','consultants_of','agents_of','independent_contractors_of','legal_advisors_of','financial_advisors_of','professional_advisors_of','accountants_of','directors_of','officers_of','lenders_of','source_named_service_recipients_of','third_parties'):
            tags.add(item[0])
    return tags
